import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Filter, FileText, ArrowUpCircle, ChevronRight, Printer } from 'lucide-react';
import { HOSPITALS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';

// Define toast state type
type ToastState = {
  message: string;
  type: 'success' | 'error';
} | null;

const HomeScreen: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const mainRef = useRef<HTMLElement>(null);

  const governorates = useMemo(() => {
    const govs = new Set(HOSPITALS.map((h) => h.gov));
    return Array.from(govs);
  }, []);

  const filteredHospitals = useMemo(() => {
    return HOSPITALS.filter((h) => {
      // 1. Filter by Governorate
      if (selectedGov && h.gov !== selectedGov) {
        return false;
      }

      // 2. Filter by Search Term
      if (!searchTerm) return true;

      const lowerTerm = searchTerm.toLowerCase();
      return (
        h.name.toLowerCase().includes(lowerTerm) ||
        h.gov.toLowerCase().includes(lowerTerm) ||
        h.area.toLowerCase().includes(lowerTerm) ||
        h.phone.toLowerCase().includes(lowerTerm)
      );
    });
  }, [searchTerm, selectedGov]);

  useEffect(() => {
    const mainEl = mainRef.current;
    if (!mainEl) return;

    const handleScroll = () => {
      setShowScrollTop(mainEl.scrollTop > 400);
    };

    mainEl.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl.removeEventListener('scroll', handleScroll);
  }, []);

  const handleScrollToTop = () => {
    mainRef.current?.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  const handlePrint = () => {
    window.print();
  };

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = (phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر حالياً", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  };

  const handleCopy = async (phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر حالياً", 'error');
      return;
    }
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم بنجاح!', 'success');
    } catch (err) {
      console.error('Failed to copy text: ', err);
      showToast('حدث خطأ أثناء نسخ الرقم.', 'error');
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative overflow-hidden print:overflow-visible print:h-auto">

      {/* AppBar */}
      <header className="bg-red-800 text-white pt-safe shadow-md z-10 relative print:bg-white print:text-black print:shadow-none print:pt-0 print:border-b-4 print:border-red-800 print:mb-8">
        {/* Buttons (Hidden in Print) */}
        <div className="absolute top-0 right-0 pt-safe p-4 z-20 flex gap-2 print:hidden">
           <button 
              onClick={onBack} 
              className="p-2 bg-red-700/80 hover:bg-red-600 rounded-full text-white transition-colors backdrop-blur-sm shadow-sm"
              aria-label="رجوع"
              title="الرجوع للصفحة الرئيسية"
           >
              <ChevronRight size={24} />
           </button>
        </div>

        <div className="absolute top-0 left-0 pt-safe p-4 z-20 print:hidden">
           <button 
              onClick={handlePrint} 
              className="p-2 bg-white/20 hover:bg-white/30 rounded-full text-white transition-colors backdrop-blur-sm shadow-sm flex items-center gap-2 px-4"
              aria-label="طباعة"
              title="تحميل كملف PDF"
           >
              <span className="hidden md:inline text-sm font-bold">تحميل PDF</span>
              <Printer size={20} />
           </button>
        </div>

        <div className="container mx-auto px-4 text-center pt-8 pb-8 print:pt-4">
          <h1 className="text-xl md:text-2xl font-bold leading-tight print:text-red-900 print:text-4xl print:mb-2">
            دليل المستشفيات والمراكز الطبية
            <span className="block text-sm md:text-base font-normal text-red-100 mt-1 print:text-gray-700 print:text-xl print:mt-2">
              المتعاقدة مع صندوق الخدمات الطبية
            </span>
          </h1>
        </div>

        {/* Search Bar (Hidden in Print) */}
        <div className="bg-red-800 px-4 pb-6 rounded-b-[2rem] print:hidden">
          <div className="relative max-w-md mx-auto">
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="ابحث باسم المستشفى أو الرقم..."
              className="w-full py-3 pr-12 pl-4 rounded-full bg-white text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-300 shadow-lg"
            />
            <div className="absolute top-0 right-0 h-full flex items-center pr-4 pointer-events-none">
              <Search className="text-gray-400" size={20} />
            </div>
          </div>
        </div>
      </header>

      {/* List Content */}
      <main ref={mainRef} className="flex-1 overflow-y-auto p-4 z-10 relative print:overflow-visible print:h-auto print:p-0 print:mx-4">
        {/* Governorate Filter (Hidden in Print) */}
        <div className="max-w-md mx-auto mb-4 print:hidden">
          <div className="bg-white/90 backdrop-blur-sm p-2 rounded-xl shadow-sm border border-gray-100 flex items-center">
            <div className="pl-3 pr-2 text-red-800">
              <Filter size={20} />
            </div>
            <select 
              value={selectedGov}
              onChange={(e) => setSelectedGov(e.target.value)}
              className="w-full bg-transparent p-2 text-gray-700 font-medium focus:outline-none cursor-pointer"
              dir="rtl"
            >
              <option value="">كل المحافظات</option>
              {governorates.map((gov) => (
                <option key={gov} value={gov}>
                  {gov}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="max-w-md mx-auto space-y-3 pb-safe print:max-w-none print:space-y-0 print:print-grid">

          {/* Print specific header for the table */}
          <div className="hidden print:block col-span-2 text-right mb-6 border-b pb-2">
             <div className="flex justify-between items-center text-gray-600 text-sm">
                <div className="flex items-center">
                  <FileText size={18} className="ml-2" />
                  <span className="font-bold">إجمالي عدد المستشفيات في هذا الدليل: {filteredHospitals.length}</span>
                </div>
                <div>المحافظة: {selectedGov || "كل المحافظات"}</div>
             </div>
          </div>

          {filteredHospitals.length > 0 ? (
            filteredHospitals.map((hospital, index) => (
              <HospitalCard 
                key={`${hospital.name}-${index}`} 
                hospital={hospital} 
                onCall={handleCall} 
                onCopy={handleCopy}
                index={index}
              />
            ))
          ) : (
            <div className="flex flex-col items-center justify-center pt-20 text-gray-400 col-span-2">
              <Search size={48} className="mb-4 opacity-50" />
              <p className="text-lg">لا توجد نتائج مطابقة</p>
            </div>
          )}

          <div className="h-10 print:hidden"></div>

          {/* Print Footer */}
          <div className="hidden print:block col-span-2 text-center text-gray-400 text-xs mt-12 border-t pt-6 break-before-avoid">
             <p className="text-gray-600 font-bold mb-1">صندوق الخدمات الطبية - دليل الجهات المتعاقدة</p>
             <p>تم استخراج هذا الملف بتاريخ {new Date().toLocaleDateString('ar-EG')} - الساعة {new Date().toLocaleTimeString('ar-EG')}</p>
             <p className="mt-2 text-[10px]">ملاحظة: يرجى مراجعة إدارة الصندوق للتأكد من استمرارية التعاقد قبل التوجه للجهة الطبية.</p>
          </div>
        </div>
      </main>

      {/* Scroll to Top Button */}
      <button
        onClick={handleScrollToTop}
        className={`print:hidden fixed bottom-6 right-6 z-20 p-3 bg-red-700/80 text-white rounded-full shadow-lg backdrop-blur-sm transition-all duration-300 ease-in-out hover:bg-red-600 active:scale-90 ${
            showScrollTop ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'
        }`}
        aria-label="العودة للأعلى"
        title="العودة للأعلى"
      >
        <ArrowUpCircle size={24} />
      </button>

      {/* Render Toast component */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </div>
  );
};

export default HomeScreen;

import React, { useState } from 'react';
import { Phone, MapPin, Building2, Copy, Check, ExternalLink } from 'lucide-react';
import { Hospital } from '../types';

interface HospitalCardProps {
  hospital: Hospital;
  onCall: (phone: string) => void;
  onCopy: (phone: string) => void;
  index: number;
}

const HospitalCard: React.FC<HospitalCardProps> = ({ hospital, onCall, onCopy, index }) => {
  const [justCopied, setJustCopied] = useState(false);

  const handleCopyClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (justCopied) return;
    onCopy(hospital.phone);
    setJustCopied(true);
    setTimeout(() => setJustCopied(false), 2000);
  };

  const isMilitary = hospital.name.includes("عسكري") || hospital.name.includes("القوات المسلحة");

  return (
    <div 
      className="bg-white rounded-2xl p-5 shadow-sm border border-slate-100 transition-all duration-300 flex flex-col md:flex-row md:items-center justify-between group break-inside-avoid animate-fade-in-up hover:shadow-xl hover:border-red-100 hover:-translate-y-1 relative overflow-hidden"
      style={{ animationFillMode: 'backwards', animationDelay: `${index * 30}ms` }}
    >
      {/* Visual Indicator for Military Hospitals */}
      {isMilitary && (
        <div className="absolute top-0 right-0 w-16 h-16 pointer-events-none">
          <div className="absolute transform rotate-45 bg-medical-accent/20 text-[10px] font-bold py-1 right-[-35px] top-[10px] w-[120px] text-center text-amber-700">
            جهة عسكرية
          </div>
        </div>
      )}

      <div className="flex-1">
        <div className="flex items-start gap-3 mb-2">
           <div className={`p-2 rounded-lg shrink-0 ${isMilitary ? 'bg-amber-50 text-amber-600' : 'bg-red-50 text-red-600'}`}>
              <Building2 size={20} />
           </div>
           <div>
              <h3 className="text-lg md:text-xl font-bold text-slate-800 leading-snug group-hover:text-medical-primary transition-colors">
                {hospital.name}
              </h3>
              <div className="flex flex-wrap items-center gap-y-1 gap-x-3 text-slate-500 text-sm mt-1">
                <div className="flex items-center gap-1">
                  <MapPin size={14} className="text-medical-secondary" />
                  <span className="font-semibold text-slate-700">{hospital.gov}</span>
                </div>
                <div className="flex items-center gap-1">
                  <div className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span>{hospital.area}</span>
                </div>
              </div>
           </div>
        </div>

        {/* Interaction Section */}
        {hospital.phone && hospital.phone !== "-" && (
          <div className="mt-4 flex items-center gap-2">
            <div className="flex items-center bg-slate-50 rounded-full px-4 py-1.5 border border-slate-100 group-hover:border-red-100 transition-colors">
              <span className="font-mono font-bold text-medical-primary tracking-wider mr-2">
                {hospital.phone}
              </span>
              <button
                onClick={handleCopyClick}
                className="print:hidden p-1.5 rounded-full text-slate-400 hover:bg-white hover:text-medical-secondary shadow-sm transition-all"
                title={justCopied ? "تم النسخ!" : "نسخ الرقم"}
              >
                {justCopied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="mt-4 md:mt-0 flex gap-2 print:hidden">
        <button
          onClick={() => onCall(hospital.phone)}
          disabled={!hospital.phone || hospital.phone === "-"}
          className={`flex-1 md:flex-none px-6 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all active:scale-95 shadow-md ${
            hospital.phone && hospital.phone !== "-"
              ? "bg-medical-primary text-white hover:bg-medical-secondary hover:shadow-red-200"
              : "bg-slate-200 text-slate-400 cursor-not-allowed shadow-none"
          }`}
        >
          <Phone size={18} />
          <span>اتصال</span>
        </button>
      </div>
    </div>
  );
};

export default HospitalCard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
