import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Search, MapPin, Hospital as HospitalIcon, ArrowUpCircle, ChevronRight, Printer, X } from 'lucide-react';
import { HOSPITALS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';

type ToastState = { message: string; type: 'success' | 'error'; } | null;

const HomeScreen: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const mainRef = useRef<HTMLElement>(null);

  const governorates = useMemo(() => {
    return Array.from(new Set(HOSPITALS.map((h) => h.gov))).sort();
  }, []);

  const filteredHospitals = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    return HOSPITALS.filter((h) => {
      const matchGov = !selectedGov || h.gov === selectedGov;
      if (!term) return matchGov;
      return matchGov && (
        h.name.toLowerCase().includes(term) ||
        h.area.toLowerCase().includes(term) ||
        h.phone.includes(term)
      );
    });
  }, [searchTerm, selectedGov]);

  const handleScroll = useCallback(() => {
    const scrollY = mainRef.current?.scrollTop || 0;
    setShowScrollTop(scrollY > 400);
    setIsScrolled(scrollY > 20);
  }, []);

  useEffect(() => {
    const mainEl = mainRef.current;
    mainEl?.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl?.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  const handleScrollToTop = () => mainRef.current?.scrollTo({ top: 0, behavior: 'smooth' });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = (phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  };

  const handleCopy = async (phone: string) => {
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم');
    } catch {
      showToast('خطأ في النسخ', 'error');
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fdfdfd] relative overflow-hidden print:bg-white font-cairo">

      {/* Dynamic Header */}
      <header className={`bg-medical-primary text-white pt-safe transition-all duration-300 z-30 shadow-2xl relative no-print ${isScrolled ? 'pb-2' : 'pb-12'}`}>
        <div className="flex justify-between items-center px-4 py-2">
          <button 
            onClick={onBack} 
            className="p-2 hover:bg-white/10 rounded-2xl transition-all active:scale-90"
          >
            <ChevronRight size={28} />
          </button>

          {!isScrolled && (
             <div className="text-center animate-fade-in-up">
                <h1 className="text-xl md:text-3xl font-black tracking-tight">الدليل الطبي</h1>
             </div>
          )}

          <button 
            onClick={() => window.print()} 
            className="p-2 bg-white/10 hover:bg-white/20 rounded-2xl border border-white/10 transition-all active:scale-90"
          >
            <Printer size={22} />
          </button>
        </div>

        {/* Brand Text - Only visible when not scrolled */}
        {!isScrolled && (
          <div className="text-center px-6 mt-4 animate-fade-in-up">
             <p className="text-red-100/70 text-sm font-bold uppercase tracking-widest">صندوق الخدمات الطبية</p>
          </div>
        )}

        {/* Floating Search Bar */}
        <div className={`transition-all duration-300 px-4 ${isScrolled ? 'mt-2' : 'absolute left-0 right-0 bottom-0 transform translate-y-1/2'}`}>
          <div className={`max-w-2xl mx-auto bg-white rounded-[2rem] shadow-2xl border border-slate-100 p-1.5 flex flex-col md:flex-row gap-1.5 transition-all ${isScrolled ? 'scale-95 opacity-90' : 'scale-100'}`}>
            <div className="flex-1 relative">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="ابحث هنا..."
                className="w-full py-3.5 pr-12 pl-4 rounded-[1.5rem] bg-slate-50 text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-medical-secondary/10 transition-all"
              />
              {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute left-3 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-red-500 transition-colors"
                >
                  <X size={18} />
                </button>
              )}
            </div>
            <div className="md:w-52 relative">
              <MapPin className="absolute right-4 top-1/2 -translate-y-1/2 text-medical-primary" size={18} />
              <select 
                value={selectedGov}
                onChange={(e) => setSelectedGov(e.target.value)}
                className="w-full py-3.5 pr-10 pl-4 rounded-[1.5rem] bg-slate-50 text-slate-700 font-black focus:outline-none cursor-pointer border border-transparent appearance-none"
              >
                <option value="">كل المحافظات</option>
                {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
              </select>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content with Smooth Scrolling */}
      <main 
        ref={mainRef} 
        className={`flex-1 overflow-y-auto px-4 pb-20 z-10 relative scroll-smooth print:overflow-visible transition-all duration-500 ${isScrolled ? 'pt-6' : 'pt-20'}`}
      >
        <div className="max-w-4xl mx-auto">

          <div className="flex items-center justify-between mb-8 px-2 no-print">
             <div className="flex items-center gap-2.5 px-5 py-2.5 bg-white rounded-2xl shadow-sm border border-slate-100">
                <HospitalIcon size={18} className="text-medical-secondary" />
                <span className="text-slate-500 font-black text-sm">
                  عثرنا على <span className="text-medical-primary text-lg px-1">{filteredHospitals.length}</span> جهة
                </span>
             </div>
          </div>

          <div className="grid grid-cols-1 gap-5 print:grid-cols-2">
            {filteredHospitals.length > 0 ? (
              filteredHospitals.map((hospital, index) => (
                <HospitalCard 
                  key={`${hospital.name}-${index}`} 
                  hospital={hospital} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-32 text-slate-300 animate-pulse-soft">
                <Search size={80} strokeWidth={1} className="mb-4 opacity-10" />
                <p className="text-xl font-black">لا توجد نتائج</p>
                <button 
                  onClick={() => {setSearchTerm(''); setSelectedGov('');}}
                  className="mt-4 text-medical-primary font-bold hover:underline"
                >
                  إعادة ضبط الفلاتر
                </button>
              </div>
            )}
          </div>

          {/* Print Footer */}
          <div className="hidden print:block mt-20 border-t-2 border-slate-100 pt-10 text-center text-slate-400">
             <p className="text-medical-primary font-black text-lg mb-2">صندوق الخدمات الطبية</p>
             <p className="text-sm">دليل الجهات الطبية المتعاقدة</p>
             <p className="text-xs mt-4 opacity-50">تاريخ الطباعة: {new Date().toLocaleDateString('ar-EG')}</p>
          </div>
        </div>
      </main>

      {/* Quick Scroll To Top */}
      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-8 right-8 z-40 p-4 bg-medical-primary text-white rounded-2xl shadow-2xl transition-all duration-500 transform ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-20 opacity-0 scale-50 pointer-events-none'
        } hover:bg-medical-secondary active:scale-75`}
      >
        <ArrowUpCircle size={30} strokeWidth={2.5} />
      </button>

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

export default HomeScreen;

