          {/* Print Footer - End of Document */}
          <div className="print-only mt-8 pt-4 border-t text-center text-xs text-gray-400">
             تم استخراج هذا المستند إلكترونياً من تطبيق الدليل الطبي - جميع الحقوق محفوظة
          </div>
        </div>
      </main>

      {/* Floating Scroll Top */}
      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-10 right-10 z-50 p-5 bg-medical-primary text-white rounded-[1.5rem] shadow-[0_20px_40px_-10px_rgba(127,29,29,0.4)] transition-all duration-700 transform ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-24 opacity-0 scale-50 pointer-events-none'
        } hover:bg-medical-secondary hover:-translate-y-2 active:scale-75`}
      >
        <ArrowUpCircle size={32} strokeWidth={2.5} />
      </button>

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

