import React, { useState, memo } from 'react';
import { Phone, MapPin, Building2, Copy, Check } from 'lucide-react';
import { Hospital } from '../types';

interface HospitalCardProps {
  hospital: Hospital;
  onCall: (phone: string) => void;
  onCopy: (phone: string) => void;
  index: number;
}

const HospitalCard: React.FC<HospitalCardProps> = memo(({ hospital, onCall, onCopy, index }) => {
  const [justCopied, setJustCopied] = useState(false);

  const handleCopyClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (justCopied || !hospital.phone || hospital.phone === "-") return;
    onCopy(hospital.phone);
    setJustCopied(true);
    setTimeout(() => setJustCopied(false), 1500);
  };

  const isMilitary = hospital.name.includes("عسكري") || hospital.name.includes("القوات المسلحة");
  const hasPhone = hospital.phone && hospital.phone !== "-";

  return (
    <div 
      className="bg-white rounded-3xl p-5 shadow-[0_8px_30px_rgb(0,0,0,0.04)] border border-slate-100/50 transition-all duration-300 flex flex-col md:flex-row md:items-center justify-between group animate-fade-in-up hover:shadow-xl hover:border-red-100 relative overflow-hidden active:scale-[0.98] will-change-transform print:shadow-none print:border print:border-slate-300 print:rounded-xl print:break-inside-avoid print:p-3"
      style={{ animationDelay: `${Math.min(index * 30, 600)}ms` }}
    >
      {isMilitary && (
        <div className="absolute top-0 right-0 w-24 h-24 pointer-events-none opacity-20 group-hover:opacity-40 transition-opacity print:opacity-10">
           <div className="absolute transform rotate-45 bg-medical-accent/40 text-[10px] font-black py-1 right-[-45px] top-[18px] w-[140px] text-center text-amber-900 uppercase tracking-tighter">
            جهة عسكرية
          </div>
        </div>
      )}

      <div className="flex-1">
        <div className="flex items-start gap-4">
           <div className={`p-3.5 rounded-2xl shrink-0 transition-all duration-500 group-hover:rotate-6 ${isMilitary ? 'bg-amber-50 text-amber-600' : 'bg-red-50 text-red-600'} print:bg-transparent print:p-1 print:text-black`}>
              <Building2 size={24} strokeWidth={2.5} />
           </div>
           <div className="space-y-1">
              <h3 className="text-lg md:text-xl font-extrabold text-slate-800 leading-tight group-hover:text-medical-primary transition-colors print:text-base print:text-black pl-8">
                {hospital.name}
              </h3>
              <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-50 rounded-full border border-slate-100 group-hover:bg-white transition-colors print:bg-transparent print:border-none print:p-0">
                  <MapPin size={14} className="text-medical-secondary print:text-gray-600" />
                  <span className="font-bold text-slate-700 text-[11px] md:text-xs print:text-gray-800">{hospital.gov}</span>
                </div>
                <span className="text-slate-400 text-xs md:text-sm font-semibold print:text-gray-500"> - {hospital.area}</span>
              </div>
           </div>
        </div>

        {hasPhone && (
          <div className="mt-5 flex items-center print:mt-2">
            <div 
              onClick={handleCopyClick}
              className="flex items-center bg-slate-50 hover:bg-slate-100 rounded-2xl px-4 py-2.5 border border-slate-100 cursor-pointer transition-all active:scale-95 group/phone relative print:bg-transparent print:border-none print:p-0"
            >
              <span className="font-mono font-black text-medical-primary tracking-widest text-lg md:text-xl mr-3 print:text-black print:text-base">
                {hospital.phone}
              </span>
              <div className="print:hidden h-8 w-8 rounded-xl flex items-center justify-center text-slate-400 bg-white shadow-sm border border-slate-100 group-hover/phone:text-medical-secondary transition-colors">
                {justCopied ? <Check size={16} className="text-emerald-500 animate-bounce" /> : <Copy size={16} />}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-5 md:mt-0 flex gap-3 print:hidden">
        <button
          onClick={() => onCall(hospital.phone)}
          disabled={!hasPhone}
          className={`flex-1 md:flex-none px-10 py-4 rounded-2xl font-black text-sm md:text-base flex items-center justify-center gap-3 transition-all active:scale-90 shadow-lg shadow-red-900/5 ${
            hasPhone
              ? "bg-medical-primary text-white hover:bg-medical-secondary hover:shadow-red-900/10"
              : "bg-slate-100 text-slate-300 cursor-not-allowed shadow-none"
          }`}
        >
          <Phone size={20} fill="currentColor" />
          <span>اتصال مباشر</span>
        </button>
      </div>
    </div>
  );
});

