              <h1 className={`${isScrolled ? 'text-lg' : 'text-2xl md:text-3xl'} font-black tracking-tight drop-shadow-sm`}>
                الدليل الطبي
              </h1>
              {!isScrolled && <p className="text-[10px] uppercase font-bold text-red-100/60 mt-1 tracking-widest animate-pulse">صندوق الخدمات الطبية</p>}
          </div>

          <button 
            onClick={handlePrintPdf} 
            className="p-2.5 bg-white/10 hover:bg-white/20 rounded-2xl border border-white/5 transition-all active:scale-75 flex flex-col items-center gap-1"
            title="حفظ كملف PDF"
          >
            <FileDown size={22} />
          </button>
        </div>

        {/* Category Toggles */}
        <div className={`flex justify-center mb-4 transition-all duration-300 ${isScrolled ? 'opacity-0 h-0 overflow-hidden pointer-events-none' : 'opacity-100 h-auto'}`}>
          <div className="bg-black/20 p-1.5 rounded-2xl flex items-center gap-1 backdrop-blur-sm border border-white/10">
            <button 
              onClick={() => setActiveTab('hospitals')}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all duration-300 ${activeTab === 'hospitals' ? 'bg-white text-medical-primary shadow-lg scale-105' : 'text-white/70 hover:bg-white/10'}`}
            >
              <Building2 size={16} className={activeTab === 'hospitals' ? 'fill-current' : ''} />
              <span>المستشفيات</span>
            </button>
            <button 
              onClick={() => setActiveTab('labs')}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all duration-300 ${activeTab === 'labs' ? 'bg-white text-medical-primary shadow-lg scale-105' : 'text-white/70 hover:bg-white/10'}`}
            >
              <Microscope size={16} className={activeTab === 'labs' ? 'fill-current' : ''} />
              <span>معامل وأشعة</span>
            </button>
          </div>
        </div>

        {/* Search & Filter Dock */}
        <div className={`transition-all duration-500 px-4 ${isScrolled ? 'mt-2 mb-1' : 'absolute left-0 right-0 bottom-0 translate-y-1/2'}`}>
          <div className={`max-w-3xl mx-auto bg-white rounded-[2.5rem] shadow-[0_15px_40px_-10px_rgba(0,0,0,0.15)] border border-slate-100/50 p-2 flex flex-col md:flex-row gap-2 transition-transform duration-300 ${isScrolled ? 'scale-95' : 'scale-100'}`}>
            <div className="flex-1 relative group">
              <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-medical-primary transition-colors" size={20} />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={activeTab === 'hospitals' ? "ابحث باسم المستشفى..." : "ابحث باسم المعمل أو المركز..."}
                className="w-full py-4 pr-14 pl-6 rounded-[2rem] bg-slate-50/80 text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-medical-secondary/5 transition-all font-bold text-sm md:text-base"
              />
              {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute left-4 top-1/2 -translate-y-1/2 p-1.5 text-slate-300 hover:text-red-500 transition-colors"
                >
                  <X size={20} />
                </button>
              )}
            </div>
            <div className="md:w-60 relative">
              <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 text-medical-primary" size={18} />
              <select 
                value={selectedGov}
                onChange={(e) => setSelectedGov(e.target.value)}
                className="w-full py-4 pr-12 pl-6 rounded-[2rem] bg-slate-50 text-slate-700 font-black focus:outline-none cursor-pointer border border-transparent hover:bg-slate-100 transition-all appearance-none text-sm"
              >
                <option value="">جميع المحافظات</option>
                {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
              </select>
              <div className="absolute left-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                <ChevronRight size={16} className="-rotate-90" />
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Dynamic Content */}
      <main 
        ref={mainRef} 
        className={`flex-1 overflow-y-auto px-4 pb-24 z-10 relative scroll-smooth transition-all duration-700 ${isScrolled ? 'pt-6' : 'pt-24'} print:pt-0 print:pb-0 print:overflow-visible print:h-auto print:block`}
      >
        <div className="max-w-4xl mx-auto print:max-w-none">

          <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 px-3 no-print gap-4">
             <div className="flex items-center gap-3 px-6 py-3 bg-white rounded-3xl shadow-sm border border-slate-100 transition-transform active:scale-95 cursor-default">
                <LayoutGrid size={18} className="text-medical-secondary animate-pulse" />
                <span className="text-slate-500 font-black text-xs md:text-sm flex flex-col md:flex-row md:items-center">
