import React, { useState, memo } from 'react';
import { Phone, MapPin, Building2, Copy, Check, Microscope } from 'lucide-react';
import { Hospital } from '../types';

interface HospitalCardProps {
  hospital: Hospital;
  onCall: (phone: string) => void;
  onCopy: (phone: string) => void;
  index: number;
  type?: 'hospital' | 'lab';
}

const HospitalCard: React.FC<HospitalCardProps> = memo(({ hospital, onCall, onCopy, index, type = 'hospital' }) => {
  const [justCopied, setJustCopied] = useState(false);

  const handleCopyClick = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    if (justCopied || !hospital.phone || hospital.phone === "-") return;
    onCopy(hospital.phone);
    setJustCopied(true);
    setTimeout(() => setJustCopied(false), 1500);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleCopyClick(e);
    }
  };

  const isMilitary = hospital.name.includes("عسكري") || hospital.name.includes("القوات المسلحة");
  const hasPhone = hospital.phone && hospital.phone !== "-";

  return (
    <div 
      className="bg-white rounded-3xl p-5 shadow-[0_8px_30px_rgb(0,0,0,0.04)] border border-slate-100/50 transition-all duration-300 flex flex-col md:flex-row md:items-center justify-between group animate-fade-in-up hover:shadow-xl hover:border-red-100 relative overflow-hidden active:scale-[0.98] will-change-transform print:shadow-none print:border print:border-slate-300 print:rounded-xl print:break-inside-avoid print:p-3"
      style={{ animationDelay: `${Math.min(index * 30, 600)}ms` }}
    >
      {isMilitary && (
        <div className="absolute top-0 right-0 w-24 h-24 pointer-events-none opacity-20 group-hover:opacity-40 transition-opacity print:opacity-10">
           <div className="absolute transform rotate-45 bg-medical-accent/40 text-[10px] font-black py-1 right-[-45px] top-[18px] w-[140px] text-center text-amber-900 uppercase tracking-tighter">
            جهة عسكرية
          </div>
        </div>
      )}

      <div className="flex-1">
        <div className="flex items-start gap-4">
           <div className={`p-3.5 rounded-2xl shrink-0 transition-all duration-500 group-hover:rotate-6 ${isMilitary ? 'bg-amber-50 text-amber-600' : 'bg-red-50 text-red-600'} print:bg-transparent print:p-1 print:text-black`}>
              {type === 'lab' ? (
                <Microscope size={24} strokeWidth={2.5} />
              ) : (
                <Building2 size={24} strokeWidth={2.5} />
              )}
           </div>
           <div className="space-y-1">
              <h3 className="text-lg md:text-xl font-extrabold text-slate-800 leading-tight group-hover:text-medical-primary transition-colors print:text-base print:text-black pl-8">
                {hospital.name}
              </h3>
              <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-50 rounded-full border border-slate-100 group-hover:bg-white transition-colors print:bg-transparent print:border-none print:p-0">
                  <MapPin size={14} className="text-medical-secondary print:text-gray-600" />
                  <span className="font-bold text-slate-700 text-[11px] md:text-xs print:text-gray-800">{hospital.gov}</span>
                </div>
                <span className="text-slate-400 text-xs md:text-sm font-semibold print:text-gray-500"> - {hospital.area}</span>
              </div>
           </div>
        </div>

        {hasPhone && (
          <div className="mt-5 flex items-center print:mt-2">
            <div 
              onClick={handleCopyClick}
              onKeyDown={handleKeyDown}
              role="button"
              tabIndex={0}
              aria-label={`نسخ رقم هاتف ${hospital.name}`}
              className="flex items-center bg-slate-50 hover:bg-slate-100 focus:bg-slate-100 focus:ring-2 focus:ring-medical-secondary/20 rounded-2xl px-4 py-2.5 border border-slate-100 cursor-pointer transition-all active:scale-95 group/phone relative print:bg-transparent print:border-none print:p-0 outline-none"
            >
              <span className="font-mono font-black text-medical-primary tracking-widest text-lg md:text-xl mr-3 print:text-black print:text-base">
                {hospital.phone}
              </span>
              <div className="print:hidden h-8 w-8 rounded-xl flex items-center justify-center text-slate-400 bg-white shadow-sm border border-slate-100 group-hover/phone:text-medical-secondary transition-colors">
                {justCopied ? <Check size={16} className="text-emerald-500 animate-bounce" /> : <Copy size={16} />}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-5 md:mt-0 flex gap-3 print:hidden">
        <button
          onClick={() => onCall(hospital.phone)}
          disabled={!hasPhone}
          className={`flex-1 md:flex-none px-10 py-4 rounded-2xl font-black text-sm md:text-base flex items-center justify-center gap-3 transition-all active:scale-90 shadow-lg shadow-red-900/5 ${
            hasPhone
              ? "bg-medical-primary text-white hover:bg-medical-secondary hover:shadow-red-900/10 focus:ring-4 focus:ring-red-900/20 outline-none"
              : "bg-slate-100 text-slate-300 cursor-not-allowed shadow-none"
          }`}
        >
          <Phone size={20} fill="currentColor" />
          <span>اتصال مباشر</span>
        </button>
      </div>
    </div>
  );
});

export default HospitalCard;

import React from 'react';
import { Home, Search, Info, LogOut } from 'lucide-react';

export type TabId = 'home' | 'search' | 'about' | 'exit';

interface BottomNavProps {
  activeTab: TabId;
  onTabChange: (tab: TabId) => void;
}

const BottomNav: React.FC<BottomNavProps> = ({ activeTab, onTabChange }) => {
  const navItems = [
    { id: 'home', icon: Home, label: 'الرئيسية' },
    { id: 'search', icon: Search, label: 'بحث' },
    { id: 'about', icon: Info, label: 'عن التطبيق' },
    { id: 'exit', icon: LogOut, label: 'خروج' },
  ];

  return (
    <div className="fixed bottom-6 left-4 right-4 z-40 flex justify-center no-print pointer-events-none">
      <div className="bg-white/90 backdrop-blur-xl border border-white/40 shadow-[0_10px_30px_-10px_rgba(0,0,0,0.2)] rounded-full px-2 py-2 flex items-center justify-between gap-1 md:gap-4 pointer-events-auto max-w-md w-full">
        {navItems.map((item) => {
          const isActive = activeTab === item.id;
          const Icon = item.icon;

          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id as TabId)}
              className={`relative flex flex-col items-center justify-center w-full h-12 rounded-full transition-all duration-300 group ${
                isActive ? 'text-medical-primary' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {isActive && (
                <span className="absolute inset-0 bg-red-50 rounded-full -z-10 scale-90 animate-fade-in-up" />
              )}
              <Icon 
                size={isActive ? 24 : 22} 
                strokeWidth={isActive ? 2.5 : 2} 
                className={`transition-all duration-300 ${isActive ? '-translate-y-1' : 'group-hover:scale-110'}`}
              />
              <span className={`text-[9px] font-bold mt-0.5 transition-all duration-300 ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2 absolute'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default BottomNav;

import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Search, MapPin, FileDown, ArrowUpCircle, ChevronRight, X, LayoutGrid, Microscope, Building2, ShieldCheck, Mail, Phone, Globe } from 'lucide-react';
import { HOSPITALS, LABS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';
import BottomNav, { TabId } from './BottomNav';
import LogoIcon from './LogoIcon';

type ToastState = { message: string; type: 'success' | 'error' | 'info'; } | null;
type EntityType = 'hospitals' | 'labs';

const HomeScreen: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeTab, setActiveTab] = useState<EntityType>('hospitals');
  const [navTab, setNavTab] = useState<TabId>('home');
  const [showAboutModal, setShowAboutModal] = useState(false);

  const mainRef = useRef<HTMLElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const currentData = useMemo(() => activeTab === 'hospitals' ? HOSPITALS : LABS, [activeTab]);

  const governorates = useMemo(() => {
    return Array.from(new Set(currentData.map((h) => h.gov))).sort();
  }, [currentData]);

  // Optimized Instant Search
  const filteredData = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    const phoneTerm = term.replace(/[\s-]/g, '');

    return currentData.filter((h) => {
      const matchGov = !selectedGov || h.gov === selectedGov;
      if (!term) return matchGov;

      const normalizedPhone = h.phone.replace(/[\s-]/g, '');

      return matchGov && (
        h.name.toLowerCase().includes(term) ||
        h.area.toLowerCase().includes(term) ||
        (phoneTerm.length > 2 && normalizedPhone.includes(phoneTerm))
      );
    });
  }, [searchTerm, selectedGov, currentData]);

  const handleScroll = useCallback(() => {
    const scrollY = mainRef.current?.scrollTop || 0;
    if (scrollY > 150 !== showScrollTop) setShowScrollTop(scrollY > 150);
    if (scrollY > 40 !== isScrolled) setIsScrolled(scrollY > 40);
  }, [showScrollTop, isScrolled]);

  useEffect(() => {
    const mainEl = mainRef.current;
    mainEl?.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl?.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  // Reset filters when switching entity tabs
  useEffect(() => {
    setSearchTerm('');
    setSelectedGov('');
    // Scroll to top
    mainRef.current?.scrollTo({ top: 0 });
  }, [activeTab]);

  const handleScrollToTop = () => mainRef.current?.scrollTo({ top: 0, behavior: 'smooth' });

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = useCallback((phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  }, []);

  const handleCopy = useCallback(async (phone: string) => {
    if (!navigator.clipboard) {
      showToast('المتصفح لا يدعم النسخ التلقائي', 'error');
      return;
    }
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم بنجاح');
    } catch {
      showToast('حدث خطأ أثناء النسخ', 'error');
    }
  }, []);

  const handlePrintPdf = () => {
    if (filteredData.length === 0) {
      showToast("لا توجد بيانات للطباعة", "error");
      return;
    }
    window.print();
  };

  const handleNavChange = (tab: TabId) => {
    if (tab === 'exit') {
      onBack();
      return;
    }

    setNavTab(tab);

    if (tab === 'home') {
      handleScrollToTop();
      setSearchTerm('');
      setSelectedGov('');
      setShowAboutModal(false);
    } else if (tab === 'search') {
      handleScrollToTop();
      setShowAboutModal(false);
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 300);
    } else if (tab === 'about') {
      setShowAboutModal(true);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fafbfc] relative overflow-hidden font-cairo print:h-auto print:overflow-visible print:block">

      {/* Report Header (Visible only in PDF/Print) */}
      <div className="print-only p-8 border-b-2 border-black mb-6">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black text-black mb-2">دليل {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل والأشعة'}</h1>
            <p className="text-sm font-bold text-gray-600">صندوق الخدمات الطبية - القوات المسلحة</p>
          </div>
          <div className="text-left">
            <p className="text-xs text-gray-500">تاريخ الاستخراج</p>
            <p className="font-mono font-bold text-lg">{new Date().toLocaleDateString('ar-EG')}</p>
          </div>
        </div>
        <div className="mt-4 py-2 border-t border-gray-200 flex justify-between text-xs font-bold text-gray-500">
          <span>عدد الجهات: {filteredData.length}</span>
          <span>{selectedGov ? `المحافظة: ${selectedGov}` : 'كافة المحافظات'}</span>
        </div>
      </div>

      {/* Premium Dynamic Header */}
      <header className={`bg-medical-primary text-white pt-safe transition-all duration-500 z-30 shadow-2xl no-print relative ${isScrolled ? 'pb-3' : 'pb-16'}`}>
        <div className="flex justify-between items-center px-4 py-3 relative z-10">
          <button 
            onClick={onBack} 
            className="p-2.5 hover:bg-white/10 rounded-2xl transition-all active:scale-75"
          >
            <ChevronRight size={30} strokeWidth={2.5} />
          </button>

          <div className={`text-center transition-all duration-500 transform ${isScrolled ? 'opacity-100 scale-100 translate-y-0' : 'opacity-100 scale-110 translate-y-2'}`}>
              <h1 className={`${isScrolled ? 'text-lg' : 'text-2xl md:text-3xl'} font-black tracking-tight drop-shadow-sm`}>
                الدليل الطبي
              </h1>
              {!isScrolled && <p className="text-[10px] uppercase font-bold text-red-100/60 mt-1 tracking-widest animate-pulse">صندوق الخدمات الطبية</p>}
          </div>

          <button 
            onClick={handlePrintPdf} 
            className="p-2.5 bg-white/10 hover:bg-white/20 rounded-2xl border border-white/5 transition-all active:scale-75 flex flex-col items-center gap-1"
            title="حفظ كملف PDF"
          >
            <FileDown size={22} />
          </button>
        </div>

        {/* Category Toggles */}
        <div className={`flex justify-center mb-4 transition-all duration-300 ${isScrolled ? 'opacity-0 h-0 overflow-hidden pointer-events-none' : 'opacity-100 h-auto'}`}>
          <div className="bg-black/20 p-1.5 rounded-2xl flex items-center gap-1 backdrop-blur-sm border border-white/10">
            <button 
              onClick={() => setActiveTab('hospitals')}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all duration-300 ${activeTab === 'hospitals' ? 'bg-white text-medical-primary shadow-lg scale-105' : 'text-white/70 hover:bg-white/10'}`}
            >
              <Building2 size={16} className={activeTab === 'hospitals' ? 'fill-current' : ''} />
              <span>المستشفيات</span>
            </button>
            <button 
              onClick={() => setActiveTab('labs')}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all duration-300 ${activeTab === 'labs' ? 'bg-white text-medical-primary shadow-lg scale-105' : 'text-white/70 hover:bg-white/10'}`}
            >
              <Microscope size={16} className={activeTab === 'labs' ? 'fill-current' : ''} />
              <span>معامل وأشعة</span>
            </button>
          </div>
        </div>

        {/* Search & Filter Dock */}
        <div className={`transition-all duration-500 px-4 ${isScrolled ? 'mt-2 mb-1' : 'absolute left-0 right-0 bottom-0 translate-y-1/2'}`}>
          <div className={`max-w-3xl mx-auto bg-white rounded-[2.5rem] shadow-[0_15px_40px_-10px_rgba(0,0,0,0.15)] border border-slate-100/50 p-2 flex flex-col md:flex-row gap-2 transition-transform duration-300 ${isScrolled ? 'scale-95' : 'scale-100'}`}>
            <div className="flex-1 relative group">
              <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-medical-primary transition-colors" size={20} />
              <input
                ref={searchInputRef}
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={activeTab === 'hospitals' ? "ابحث باسم المستشفى..." : "ابحث باسم المعمل أو المركز..."}
                className="w-full py-4 pr-14 pl-6 rounded-[2rem] bg-slate-50/80 text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-medical-secondary/5 transition-all font-bold text-sm md:text-base"
              />
              {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute left-4 top-1/2 -translate-y-1/2 p-1.5 text-slate-300 hover:text-red-500 transition-colors"
                >
                  <X size={20} />
                </button>
              )}
            </div>
            <div className="md:w-60 relative">
              <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 text-medical-primary" size={18} />
              <select 
                value={selectedGov}
                onChange={(e) => setSelectedGov(e.target.value)}
                className="w-full py-4 pr-12 pl-6 rounded-[2rem] bg-slate-50 text-slate-700 font-black focus:outline-none cursor-pointer border border-transparent hover:bg-slate-100 transition-all appearance-none text-sm"
              >
                <option value="">جميع المحافظات</option>
                {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
              </select>
              <div className="absolute left-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                <ChevronRight size={16} className="-rotate-90" />
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Dynamic Content */}
      <main 
        ref={mainRef} 
        className={`flex-1 overflow-y-auto px-4 pb-32 z-10 relative scroll-smooth transition-all duration-700 ${isScrolled ? 'pt-6' : 'pt-24'} print:pt-0 print:pb-0 print:overflow-visible print:h-auto print:block`}
      >
        <div className="max-w-4xl mx-auto print:max-w-none">

          <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 px-3 no-print gap-4">
             <div className="flex items-center gap-3 px-6 py-3 bg-white rounded-3xl shadow-sm border border-slate-100 transition-transform active:scale-95 cursor-default">
                <LayoutGrid size={18} className="text-medical-secondary animate-pulse" />
                <span className="text-slate-500 font-black text-xs md:text-sm flex flex-col md:flex-row md:items-center">
                  <span>{activeTab === 'hospitals' ? 'المستشفيات' : 'المراكز'} المعروضة: <span className="text-medical-primary text-xl md:text-2xl px-1.5">{filteredData.length}</span></span>
                </span>
             </div>

             {searchTerm && (
               <button 
                onClick={() => {setSearchTerm(''); setSelectedGov('');}}
                className="text-xs font-black text-medical-secondary bg-red-50 px-4 py-2 rounded-full hover:bg-red-100 transition-colors self-start md:self-auto"
               >
                 مسح الفلاتر
               </button>
             )}
          </div>

          <div className="grid grid-cols-1 gap-6 print-grid">
            {filteredData.length > 0 ? (
              filteredData.map((item, index) => (
                <HospitalCard 
                  key={`${item.name}-${index}`} 
                  hospital={item} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                  type={activeTab === 'labs' ? 'lab' : 'hospital'}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-40 text-slate-300 animate-pulse-soft">
                <div className="relative mb-6">
                   <Search size={100} strokeWidth={1} className="opacity-10" />
                   <X size={40} className="absolute bottom-0 right-0 text-red-500/20" />
                </div>
                <p className="text-2xl font-black text-slate-400">لا توجد جهات مطابقة</p>
                <p className="text-sm font-bold mt-2 opacity-60">جرب كتابة اسم مختلف أو البحث في محافظة أخرى</p>
              </div>
            )}
          </div>

          {/* Print Footer - End of Document */}
          <div className="print-only mt-8 pt-4 border-t text-center text-xs text-gray-400">
             تم استخراج هذا المستند إلكترونياً - جميع الحقوق محفوظة للمطور أحمد عماد
          </div>

          {/* Screen Footer */}
          <div className="mt-10 mb-4 flex flex-col items-center justify-center text-slate-300 no-print opacity-60 hover:opacity-100 transition-opacity">
            <p className="text-[8px] font-bold">تصميم وتطوير</p>
            <p className="text-[10px] font-black mt-0.5">أحمد عماد</p>
          </div>
        </div>
      </main>

      {/* Bottom Navigation */}
      <BottomNav activeTab={navTab} onTabChange={handleNavChange} />

      {/* Floating Scroll Top (Visible only if scrolled deep) */}
      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-24 right-6 z-30 p-4 bg-white text-medical-primary rounded-full shadow-[0_10px_30px_-5px_rgba(0,0,0,0.15)] transition-all duration-700 transform border border-slate-100 ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-24 opacity-0 scale-50 pointer-events-none'
        } hover:bg-medical-primary hover:text-white active:scale-75`}
      >
        <ArrowUpCircle size={24} strokeWidth={2.5} />
      </button>

      {/* About Modal */}
      {showAboutModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in-up" onClick={() => setShowAboutModal(false)}>
           <div className="bg-white w-full max-w-sm rounded-[2.5rem] p-6 relative overflow-hidden shadow-2xl" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowAboutModal(false)} className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors">
                <X size={20} />
              </button>

              <div className="flex flex-col items-center text-center">
                 <div className="w-24 h-24 mb-6 rounded-3xl bg-slate-50 border-4 border-slate-100 p-4 shadow-inner">
                   <LogoIcon className="w-full h-full drop-shadow-md" />
                 </div>

                 <h2 className="text-2xl font-black text-slate-800 mb-1">الدليل الطبي</h2>
                 <p className="text-sm font-bold text-medical-secondary mb-6">صندوق الخدمات الطبية</p>

                 <div className="space-y-3 w-full">
                    <div className="flex items-center gap-3 p-4 rounded-2xl bg-slate-50 border border-slate-100">
                       <ShieldCheck className="text-emerald-500" size={20} />
                       <div className="text-right flex-1">
                          <p className="text-[10px] font-bold text-slate-400 uppercase">الإصدار</p>
                          <p className="font-bold text-slate-700">v1.2.0 (أحدث نسخة)</p>
                       </div>
                    </div>

                    <div className="flex items-center gap-3 p-4 rounded-2xl bg-slate-50 border border-slate-100">
                       <Globe className="text-blue-500" size={20} />
                       <div className="text-right flex-1">
                          <p className="text-[10px] font-bold text-slate-400 uppercase">قاعدة البيانات</p>
                          <p className="font-bold text-slate-700">محدثة: فبراير 2025</p>
                       </div>
                    </div>

                    <div className="p-4 rounded-2xl bg-medical-primary/5 border border-medical-primary/10 mt-4">
                       <p className="text-xs font-bold text-medical-primary leading-relaxed">
                          تم تصميم هذا التطبيق لتسهيل الوصول إلى خدمات الرعاية الطبية لأفراد القوات المسلحة وأسرهم.
                       </p>
                    </div>
                 </div>

                 <div className="mt-8 pt-6 border-t border-slate-100 w-full flex flex-col items-center">
                    <p className="text-xs text-slate-400 mb-1">تم التطوير بواسطة</p>
                    <p className="font-black text-slate-800 text-lg">أحمد عماد</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

export default HomeScreen;

