};

export default HomeScreen;

import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Search, MapPin, FileDown, ArrowUpCircle, ChevronRight, X, LayoutGrid, Microscope, Building2, ShieldCheck, Globe } from 'lucide-react';
import { HOSPITALS, LABS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';
import BottomNav, { TabId } from './BottomNav';
import LogoIcon from './LogoIcon';

type ToastState = { message: string; type: 'success' | 'error' | 'info'; } | null;
type EntityType = 'hospitals' | 'labs';

const HomeScreen: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeTab, setActiveTab] = useState<EntityType>('hospitals');
  const [navTab, setNavTab] = useState<TabId>('home');
  const [showAboutModal, setShowAboutModal] = useState(false);

  const mainRef = useRef<HTMLElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const currentData = useMemo(() => activeTab === 'hospitals' ? HOSPITALS : LABS, [activeTab]);

  const governorates = useMemo(() => {
    return Array.from(new Set(currentData.map((h) => h.gov))).sort();
  }, [currentData]);

  const filteredData = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    const phoneTerm = term.replace(/[\s-]/g, '');

    return currentData.filter((h) => {
      const matchGov = !selectedGov || h.gov === selectedGov;
      if (!term) return matchGov;

      const normalizedPhone = h.phone.replace(/[\s-]/g, '');

      return matchGov && (
        h.name.toLowerCase().includes(term) ||
        h.area.toLowerCase().includes(term) ||
        (phoneTerm.length > 2 && normalizedPhone.includes(phoneTerm))
      );
    });
  }, [searchTerm, selectedGov, currentData]);

  const handleScroll = useCallback(() => {
    const scrollY = mainRef.current?.scrollTop || 0;
    if (scrollY > 150 !== showScrollTop) setShowScrollTop(scrollY > 150);
    if (scrollY > 20 !== isScrolled) setIsScrolled(scrollY > 20);
  }, [showScrollTop, isScrolled]);

  useEffect(() => {
    const mainEl = mainRef.current;
    mainEl?.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl?.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  useEffect(() => {
    setSearchTerm('');
    setSelectedGov('');
    mainRef.current?.scrollTo({ top: 0 });
  }, [activeTab]);

  const handleScrollToTop = () => mainRef.current?.scrollTo({ top: 0, behavior: 'smooth' });

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = useCallback((phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  }, []);

  const handleCopy = useCallback(async (phone: string) => {
    if (!navigator.clipboard) {
      showToast('المتصفح لا يدعم النسخ التلقائي', 'error');
      return;
    }
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم بنجاح');
    } catch {
      showToast('حدث خطأ أثناء النسخ', 'error');
    }
  }, []);

  const handlePrintPdf = () => {
    if (filteredData.length === 0) {
      showToast("لا توجد بيانات للطباعة", "error");
      return;
    }
    window.print();
  };

  const handleNavChange = (tab: TabId) => {
    if (tab === 'exit') {
      onBack();
      return;
    }

    setNavTab(tab);

    if (tab === 'home') {
      handleScrollToTop();
      setSearchTerm('');
      setSelectedGov('');
      setShowAboutModal(false);
    } else if (tab === 'search') {
      handleScrollToTop();
      setShowAboutModal(false);
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 300);
    } else if (tab === 'about') {
      setShowAboutModal(true);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fafbfc] relative overflow-hidden font-cairo print:h-auto print:overflow-visible print:block">

      {/* Print Header */}
      <div className="print-only p-8 border-b-2 border-black mb-6">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black text-black mb-2">دليل {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل والأشعة'}</h1>
            <p className="text-sm font-bold text-gray-600">صندوق الخدمات الطبية - القوات المسلحة</p>
          </div>
          <div className="text-left">
            <p className="text-xs text-gray-500">تاريخ الاستخراج</p>
            <p className="font-mono font-bold text-lg">{new Date().toLocaleDateString('ar-EG')}</p>
          </div>
        </div>
      </div>

      {/* Minimalist Header */}
      <header className={`bg-[#fafbfc]/90 backdrop-blur-md pt-safe transition-all duration-300 z-30 no-print sticky top-0 ${isScrolled ? 'border-b border-slate-200/60 shadow-sm' : ''}`}>
        <div className="flex flex-col px-6 pt-6 pb-2">

          {/* Top Row: Back, Title, Actions */}
          <div className="flex justify-between items-center mb-6">
            <button 
              onClick={onBack} 
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 hover:bg-slate-200 text-slate-700 transition-all active:scale-90"
            >
              <ChevronRight size={22} strokeWidth={2.5} />
            </button>

            <div className={`text-center transition-all duration-300 ${isScrolled ? 'opacity-0 scale-90 h-0 w-0 overflow-hidden' : 'opacity-100 scale-100'}`}>
               <p className="text-xs font-bold text-medical-primary uppercase tracking-widest mb-1">صندوق الخدمات الطبية</p>
               <h1 className="text-2xl font-black text-slate-900 tracking-tight">الدليل الطبي</h1>
            </div>

            {/* Scrolled Title (replaces center title) */}
             <div className={`absolute left-1/2 -translate-x-1/2 font-black text-lg text-slate-900 transition-all duration-300 ${isScrolled ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}`}>
                {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل'}
             </div>

            <button 
              onClick={handlePrintPdf} 
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 hover:bg-slate-200 text-slate-700 transition-all active:scale-90"
              title="طباعة"
            >
              <FileDown size={20} strokeWidth={2} />
            </button>
          </div>

          {/* Search Bar - Minimalist */}
          <div className="relative z-20 group">
             <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none">
                <Search className="text-slate-400 group-focus-within:text-medical-primary transition-colors" size={20} />
             </div>
             <input
                ref={searchInputRef}
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={activeTab === 'hospitals' ? "ابحث باسم المستشفى..." : "ابحث باسم المعمل..."}
                className="w-full py-4 pr-12 pl-4 bg-white border border-slate-200 rounded-2xl text-slate-900 placeholder:text-slate-400 font-semibold focus:outline-none focus:border-medical-primary/50 focus:ring-4 focus:ring-medical-primary/5 transition-all shadow-sm group-hover:shadow-md"
             />
             {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 left-4 flex items-center text-slate-400 hover:text-red-500 transition-colors"
                >
                  <X size={18} />
                </button>
             )}
          </div>

          {/* Filters Row */}
          <div className="flex gap-3 mt-3 overflow-x-auto pb-2 no-scrollbar">
             {/* Tab Switcher */}
             <div className="flex bg-slate-100 p-1 rounded-xl shrink-0">
                <button 
                  onClick={() => setActiveTab('hospitals')}
                  className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'hospitals' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  مستشفيات
                </button>
                <button 
                  onClick={() => setActiveTab('labs')}
                  className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'labs' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  معامل
                </button>
             </div>

             {/* Gov Filter */}
             <div className="relative shrink-0 min-w-[140px]">
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                   <MapPin size={14} />
                </div>
                <select 
                  value={selectedGov}
                  onChange={(e) => setSelectedGov(e.target.value)}
                  className="w-full h-full pl-8 pr-9 py-2 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-700 focus:outline-none focus:border-medical-primary/30 appearance-none"
                >
                  <option value="">كل المحافظات</option>
                  {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
                </select>
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                  <ChevronRight size={14} className="-rotate-90" />
                </div>
             </div>
          </div>

          {/* Results Count (Subtle) */}
          <div className="flex items-center gap-2 mt-2 px-1">
             <LayoutGrid size={14} className="text-slate-400" />
             <span className="text-xs font-semibold text-slate-500">
                تم العثور على <span className="text-slate-900 font-bold">{filteredData.length}</span> نتيجة
             </span>
          </div>
        </div>
      </header>

      {/* Dynamic Content */}
      <main 
        ref={mainRef} 
        className="flex-1 overflow-y-auto px-4 pb-32 pt-2 scroll-smooth z-10"
      >
        <div className="max-w-4xl mx-auto">
          <div className="grid grid-cols-1 gap-4 print-grid">
            {filteredData.length > 0 ? (
              filteredData.map((item, index) => (
                <HospitalCard 
                  key={`${item.name}-${index}`} 
                  hospital={item} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                  type={activeTab === 'labs' ? 'lab' : 'hospital'}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-slate-300">
                <Search size={60} strokeWidth={1} className="mb-4 opacity-20" />
                <p className="text-lg font-bold text-slate-400">لا توجد نتائج</p>
                <p className="text-xs font-medium mt-2 opacity-60">جرب البحث بكلمات مختلفة</p>
              </div>
            )}
          </div>

          <div className="print-only mt-8 pt-4 border-t text-center text-xs text-gray-400">
             تم استخراج هذا المستند إلكترونياً
          </div>

          <div className="mt-10 mb-4 flex flex-col items-center justify-center text-slate-300 no-print opacity-60">
            <LogoIcon className="w-8 h-8 opacity-20 grayscale mb-2" />
            <p className="text-[10px] font-medium">تصميم وتطوير: أحمد عماد</p>
          </div>
        </div>
      </main>

      {/* Bottom Navigation */}
      <BottomNav activeTab={navTab} onTabChange={handleNavChange} />

      {/* Floating Scroll Top */}
      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-24 right-6 z-30 p-3 bg-slate-900 text-white rounded-full shadow-lg transition-all duration-500 transform ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-75 pointer-events-none'
        } hover:bg-black active:scale-90`}
      >
        <ArrowUpCircle size={24} strokeWidth={2} />
      </button>

      {/* Minimalist About Modal */}
      {showAboutModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-fade-in-up" onClick={() => setShowAboutModal(false)}>
           <div className="bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl relative" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowAboutModal(false)} className="absolute top-6 right-6 p-2 bg-slate-50 rounded-full text-slate-400 hover:text-black transition-colors">
                <X size={20} />
              </button>

              <div className="flex flex-col items-center text-center">
                 <div className="w-20 h-20 mb-6 flex items-center justify-center">
                   <LogoIcon className="w-full h-full" />
                 </div>

                 <h2 className="text-2xl font-black text-slate-900 mb-1">الدليل الطبي</h2>
                 <p className="text-xs font-bold text-slate-500 tracking-wider uppercase mb-8">صندوق الخدمات الطبية</p>

                 <div className="w-full space-y-4">
                    <div className="flex justify-between items-center py-3 border-b border-slate-100">
                       <div className="flex items-center gap-3 text-slate-600">
                          <ShieldCheck size={18} />
                          <span className="text-sm font-bold">الإصدار</span>
                       </div>
                       <span className="font-mono text-sm font-bold text-slate-900">1.2.0</span>
                    </div>

                    <div className="flex justify-between items-center py-3 border-b border-slate-100">
                       <div className="flex items-center gap-3 text-slate-600">
                          <Globe size={18} />
                          <span className="text-sm font-bold">التحديث</span>
                       </div>
                       <span className="text-sm font-bold text-slate-900">فبراير 2025</span>
                    </div>
                 </div>

                 <p className="text-[10px] text-slate-400 mt-8 leading-relaxed max-w-[200px]">
                    تم تصميم هذا التطبيق لتسهيل الوصول إلى الخدمات الطبية
                 </p>
              </div>
           </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

export default HomeScreen;

import React, { useState, memo } from 'react';
import { Phone, MapPin, Building2, Copy, Check, Microscope } from 'lucide-react';
import { Hospital } from '../types';

interface HospitalCardProps {
  hospital: Hospital;
  onCall: (phone: string) => void;
  onCopy: (phone: string) => void;
  index: number;
  type?: 'hospital' | 'lab';
}

const HospitalCard: React.FC<HospitalCardProps> = memo(({ hospital, onCall, onCopy, index, type = 'hospital' }) => {
  const [justCopied, setJustCopied] = useState(false);

  const handleCopyClick = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    if (justCopied || !hospital.phone || hospital.phone === "-") return;
    onCopy(hospital.phone);
    setJustCopied(true);
    setTimeout(() => setJustCopied(false), 1500);
  };

  const isMilitary = hospital.name.includes("عسكري") || hospital.name.includes("القوات المسلحة");
  const hasPhone = hospital.phone && hospital.phone !== "-";

  return (
    <div 
      className="group bg-white rounded-[1.5rem] p-5 md:p-6 transition-all duration-300 animate-fade-in-up hover:shadow-lg hover:-translate-y-1 relative overflow-hidden border border-transparent hover:border-slate-100 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07)] print:shadow-none print:border-slate-300 print:rounded-xl print:break-inside-avoid"
      style={{ animationDelay: `${Math.min(index * 50, 600)}ms` }}
    >
      {/* Military Badge - Minimal */}
      {isMilitary && (
        <div className="absolute top-5 left-5 pointer-events-none opacity-10 md:opacity-100">
           <div className="bg-amber-50 text-amber-700 text-[10px] font-black px-2 py-1 rounded-md border border-amber-100/50">
            جهة عسكرية
          </div>
        </div>
      )}

      <div className="flex flex-col gap-4">
        {/* Header Section */}
        <div className="flex items-start gap-4">
           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 transition-colors duration-300 ${isMilitary ? 'bg-amber-100/30 text-amber-600' : 'bg-slate-100 text-slate-600 group-hover:bg-medical-primary/10 group-hover:text-medical-primary'}`}>
              {type === 'lab' ? (
                <Microscope size={22} strokeWidth={2} />
              ) : (
                <Building2 size={22} strokeWidth={2} />
              )}
           </div>

           <div className="flex-1 min-w-0 pt-0.5">
              <h3 className="text-lg font-black text-slate-900 leading-snug group-hover:text-medical-primary transition-colors truncate-multiline">
                {hospital.name}
              </h3>
              <div className="flex items-center gap-1.5 mt-1.5 text-slate-500">
                <MapPin size={12} />
                <span className="text-xs font-bold">{hospital.gov} <span className="text-slate-300 mx-1">|</span> {hospital.area}</span>
              </div>
           </div>
        </div>

        {/* Action Section */}
        <div className="flex items-center gap-3 mt-1 pt-4 border-t border-slate-50 print:border-none">
           {hasPhone ? (
             <>
                <div 
                  onClick={handleCopyClick}
                  className="flex-1 flex items-center justify-between bg-slate-50 hover:bg-slate-100 rounded-xl px-4 py-3 cursor-pointer transition-colors group/phone"
                >
                   <span className="font-mono font-bold text-slate-700 text-lg tracking-wide">{hospital.phone}</span>
                   <div className="text-slate-300 group-hover/phone:text-medical-primary transition-colors">
                      {justCopied ? <Check size={16} /> : <Copy size={16} />}
                   </div>
                </div>

                <button
                  onClick={() => onCall(hospital.phone)}
                  className="w-14 h-14 flex items-center justify-center rounded-xl bg-slate-900 text-white shadow-md shadow-slate-200 hover:bg-medical-primary hover:shadow-medical-primary/20 hover:scale-105 active:scale-95 transition-all"
                  title="اتصال"
                >
                   <Phone size={22} fill="currentColor" />
