             </>
           ) : (
             <div className="w-full bg-slate-50 rounded-xl px-4 py-3 text-center">
               <span className="text-sm font-bold text-slate-400">الرقم غير متوفر</span>
             </div>
           )}
        </div>
      </div>
    </div>
  );
});

