             />
             {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 left-4 flex items-center text-slate-400 hover:text-red-500 transition-colors"
                >
                  <X size={18} />
                </button>
             )}
          </div>

          {/* Filters Row */}
          <div className="flex gap-3 mt-3 overflow-x-auto pb-2 no-scrollbar">
             {/* Tab Switcher */}
             <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-xl shrink-0 border border-transparent dark:border-slate-800">
                <button 
                  onClick={() => setActiveTab('hospitals')}
                  className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'hospitals' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                  مستشفيات
                </button>
                <button 
                  onClick={() => setActiveTab('labs')}
                  className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'labs' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
