                  className="w-full h-full pl-8 pr-9 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-sm font-bold text-slate-700 dark:text-slate-200 focus:outline-none focus:border-medical-primary/30 appearance-none"
                >
                  <option value="">كل المحافظات</option>
                  {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
                </select>
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                  <ChevronRight size={14} className="-rotate-90" />
                </div>
             </div>
          </div>

          {/* Results Count (Subtle) */}
          <div className="flex items-center gap-2 mt-2 px-1">
             <LayoutGrid size={14} className="text-slate-400" />
             <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
