    <div 
      className="group bg-white dark:bg-[#111827] rounded-[1.5rem] p-5 md:p-6 transition-all duration-300 animate-fade-in-up hover:shadow-lg hover:-translate-y-1 relative overflow-hidden border border-transparent hover:border-slate-100 dark:hover:border-slate-800 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07)] dark:shadow-none print:shadow-none print:border-slate-300 print:rounded-xl print:break-inside-avoid"
