        {navItems.map((item) => {
          const isActive = activeTab === item.id;
          const Icon = item.icon;

          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id as TabId)}
              className={`relative flex items-center justify-center w-10 h-10 rounded-xl transition-all duration-300 ${
