import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Search, MapPin, FileDown, ArrowUpCircle, ChevronRight, X, LayoutGrid, ShieldCheck, Globe, Moon, Sun, Building2, Microscope } from 'lucide-react';
import { HOSPITALS, LABS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';
import BottomNav, { TabId } from './BottomNav';
import LogoIcon from './LogoIcon';

type ToastState = { message: string; type: 'success' | 'error' | 'info'; } | null;
type EntityType = 'hospitals' | 'labs';

interface HomeScreenProps {
  onBack: () => void;
  isDark: boolean;
  toggleTheme: () => void;
}

const HomeScreen: React.FC<HomeScreenProps> = ({ onBack, isDark, toggleTheme }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeTab, setActiveTab] = useState<EntityType>('hospitals');
  const [navTab, setNavTab] = useState<TabId>('home');
  const [showAboutModal, setShowAboutModal] = useState(false);

  const mainRef = useRef<HTMLElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const currentData = useMemo(() => activeTab === 'hospitals' ? HOSPITALS : LABS, [activeTab]);

  const governorates = useMemo(() => {
    return Array.from(new Set(currentData.map((h) => h.gov))).sort();
  }, [currentData]);

  const filteredData = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    const phoneTerm = term.replace(/[\s-]/g, '');

    return currentData.filter((h) => {
      const matchGov = !selectedGov || h.gov === selectedGov;
      if (!term) return matchGov;

      const normalizedPhone = h.phone.replace(/[\s-]/g, '');

      return matchGov && (
        h.name.toLowerCase().includes(term) ||
        h.area.toLowerCase().includes(term) ||
        (phoneTerm.length > 2 && normalizedPhone.includes(phoneTerm))
      );
    });
  }, [searchTerm, selectedGov, currentData]);

  const handleScroll = useCallback(() => {
    const scrollY = mainRef.current?.scrollTop || 0;
    if (scrollY > 150 !== showScrollTop) setShowScrollTop(scrollY > 150);
    if (scrollY > 20 !== isScrolled) setIsScrolled(scrollY > 20);
  }, [showScrollTop, isScrolled]);

  useEffect(() => {
    const mainEl = mainRef.current;
    mainEl?.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl?.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  useEffect(() => {
    setSearchTerm('');
    setSelectedGov('');
    mainRef.current?.scrollTo({ top: 0 });
  }, [activeTab]);

  const handleScrollToTop = () => mainRef.current?.scrollTo({ top: 0, behavior: 'smooth' });

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = useCallback((phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  }, []);

  const handleCopy = useCallback(async (phone: string) => {
    if (!navigator.clipboard) {
      showToast('المتصفح لا يدعم النسخ التلقائي', 'error');
      return;
    }
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم بنجاح');
    } catch {
      showToast('حدث خطأ أثناء النسخ', 'error');
    }
  }, []);

  const handlePrintPdf = () => {
    if (filteredData.length === 0) {
      showToast("لا توجد بيانات للطباعة", "error");
      return;
    }
    window.print();
  };

  const handleNavChange = (tab: TabId) => {
    if (tab === 'exit') {
      onBack();
      return;
    }

    setNavTab(tab);

    if (tab === 'home') {
      handleScrollToTop();
      setSearchTerm('');
      setSelectedGov('');
      setShowAboutModal(false);
    } else if (tab === 'search') {
      handleScrollToTop();
      setShowAboutModal(false);
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 300);
    } else if (tab === 'about') {
      setShowAboutModal(true);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fafbfc] dark:bg-[#020617] relative overflow-hidden font-cairo print:h-auto print:overflow-visible print:block transition-colors duration-300">

      {/* Print Header */}
      <div className="print-only p-8 border-b-2 border-black mb-6">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black text-black mb-2">دليل {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل والأشعة'}</h1>
            <p className="text-sm font-bold text-gray-600">صندوق الخدمات الطبية - القوات المسلحة</p>
          </div>
          <div className="text-left">
            <p className="text-xs text-gray-500">تاريخ الاستخراج</p>
            <p className="font-mono font-bold text-lg">{new Date().toLocaleDateString('ar-EG')}</p>
          </div>
        </div>
      </div>

      {/* Minimalist Compact Header */}
      <header className={`bg-[#fafbfc]/95 dark:bg-[#020617]/95 backdrop-blur-md pt-safe transition-all duration-300 z-30 no-print sticky top-0 ${isScrolled ? 'border-b border-slate-200/60 dark:border-slate-800/60 shadow-sm' : ''}`}>
        <div className="flex flex-col px-4 pt-4 pb-2">

          {/* Top Row: Back, Title, Actions - Reduced height and margin */}
          <div className="flex justify-between items-center mb-3">
            <button 
              onClick={onBack} 
              className="w-9 h-9 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 transition-all active:scale-90"
            >
              <ChevronRight size={18} strokeWidth={2.5} />
            </button>

            <div className={`flex flex-col items-center transition-all duration-300 ${isScrolled ? 'opacity-0 scale-90 h-0 w-0 overflow-hidden' : 'opacity-100 scale-100'}`}>
               <LogoIcon className="w-10 h-10 mb-1 text-slate-900 dark:text-white" />
               <h1 className="text-lg font-black text-slate-900 dark:text-white tracking-tight">الدليل الطبي</h1>
            </div>

            {/* Scrolled Title */}
             <div className={`absolute left-1/2 -translate-x-1/2 font-black text-base text-slate-900 dark:text-white transition-all duration-300 ${isScrolled ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}`}>
                {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل'}
             </div>

             <div className="flex items-center gap-2">
               <button 
                onClick={toggleTheme} 
                className="w-9 h-9 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-yellow-400 transition-all active:scale-90"
                title="تغيير المظهر"
              >
                {isDark ? <Sun size={18} strokeWidth={2} /> : <Moon size={18} strokeWidth={2} />}
              </button>

              <button 
                onClick={handlePrintPdf} 
                className="w-9 h-9 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 transition-all active:scale-90"
                title="طباعة"
              >
                <FileDown size={18} strokeWidth={2} />
              </button>
             </div>
          </div>

          {/* Search Bar - More Compact */}
          <div className="relative z-20 group">
             <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none">
                <Search className="text-slate-400 group-focus-within:text-slate-900 dark:group-focus-within:text-white transition-colors" size={18} />
             </div>
             <input
                ref={searchInputRef}
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={activeTab === 'hospitals' ? "ابحث باسم المستشفى..." : "ابحث باسم المعمل..."}
                className="w-full py-2.5 pr-10 pl-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-sm text-slate-900 dark:text-white placeholder:text-slate-400 font-bold focus:outline-none focus:border-slate-400 dark:focus:border-slate-600 focus:ring-4 focus:ring-slate-100 dark:focus:ring-slate-800/20 transition-all shadow-sm group-hover:shadow-md dark:shadow-none"
             />
             {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 left-3 flex items-center text-slate-400 hover:text-red-500 transition-colors"
                >
                  <X size={16} />
                </button>
             )}
          </div>

          {/* Filters Row - Compact */}
          <div className="flex gap-2 mt-2 overflow-x-auto pb-1 no-scrollbar">
             {/* Tab Switcher */}
             <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-lg shrink-0 border border-transparent dark:border-slate-800">
                <button 
                  onClick={() => setActiveTab('hospitals')}
                  className={`flex items-center gap-1.5 px-3 py-1 rounded-md text-xs font-bold transition-all ${activeTab === 'hospitals' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                  <Building2 size={14} strokeWidth={2.5} />
                  <span>مستشفيات</span>
                </button>
                <button 
                  onClick={() => setActiveTab('labs')}
                  className={`flex items-center gap-1.5 px-3 py-1 rounded-md text-xs font-bold transition-all ${activeTab === 'labs' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                  <Microscope size={14} strokeWidth={2.5} />
                  <span>معامل</span>
                </button>
             </div>

             {/* Gov Filter */}
             <div className="relative shrink-0 min-w-[120px]">
                <div className="absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                   <MapPin size={12} />
                </div>
                <select 
                  value={selectedGov}
                  onChange={(e) => setSelectedGov(e.target.value)}
                  className="w-full h-full pl-6 pr-7 py-1.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg text-xs font-bold text-slate-700 dark:text-slate-200 focus:outline-none focus:border-slate-300 dark:focus:border-slate-700 appearance-none"
                >
                  <option value="">كل المحافظات</option>
                  {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
                </select>
                <div className="absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                  <ChevronRight size={12} className="-rotate-90" />
                </div>
             </div>
          </div>

          {/* Results Count (Hidden on scroll or made tiny) */}
          {!isScrolled && (
             <div className="flex items-center gap-1.5 mt-1 px-1">
                <LayoutGrid size={12} className="text-slate-400" />
                <span className="text-[10px] font-semibold text-slate-500 dark:text-slate-400">
                   <span className="text-slate-900 dark:text-slate-200 font-bold">{filteredData.length}</span> نتيجة
                </span>
             </div>
          )}
        </div>
      </header>

      {/* Dynamic Content - Adjusted Spacing */}
      <main 
        ref={mainRef} 
        className="flex-1 overflow-y-auto px-4 pb-28 pt-2 scroll-smooth z-10"
      >
        <div className="max-w-3xl mx-auto">
          <div className="grid grid-cols-1 gap-3 print-grid">
            {filteredData.length > 0 ? (
              filteredData.map((item, index) => (
                <HospitalCard 
                  key={`${item.name}-${index}`} 
                  hospital={item} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                  type={activeTab === 'labs' ? 'lab' : 'hospital'}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-slate-300 dark:text-slate-700">
                <Search size={50} strokeWidth={1} className="mb-4 opacity-20" />
                <p className="text-base font-bold text-slate-400 dark:text-slate-600">لا توجد نتائج</p>
                <p className="text-[10px] font-medium mt-1 opacity-60">جرب البحث بكلمات مختلفة</p>
              </div>
            )}
          </div>

          <div className="print-only mt-8 pt-4 border-t text-center text-xs text-gray-400">
             تم استخراج هذا المستند إلكترونياً
          </div>

          <div className="mt-8 mb-4 flex flex-col items-center justify-center text-slate-200 dark:text-slate-800 no-print opacity-60">
            <LogoIcon className="w-5 h-5 opacity-20 grayscale mb-1" />
            <p className="text-[10px] font-medium">تصميم وتطوير: أحمد عماد</p>
          </div>
        </div>
      </main>

      {/* Bottom Navigation */}
      <BottomNav activeTab={navTab} onTabChange={handleNavChange} />

      {/* Floating Scroll Top - Smaller */}
      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-20 right-4 z-30 p-2.5 bg-slate-900 dark:bg-slate-700 text-white rounded-full shadow-lg transition-all duration-500 transform ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-75 pointer-events-none'
        } hover:bg-black dark:hover:bg-slate-600 active:scale-90`}
      >
        <ArrowUpCircle size={20} strokeWidth={2} />
      </button>

      {/* Minimalist About Modal */}
      {showAboutModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-fade-in-up" onClick={() => setShowAboutModal(false)}>
           <div className="bg-white dark:bg-slate-900 w-full max-w-xs rounded-3xl p-6 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowAboutModal(false)} className="absolute top-4 right-4 p-1.5 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400 hover:text-black dark:hover:text-white transition-colors">
                <X size={16} />
              </button>

              <div className="flex flex-col items-center text-center">
                 <div className="w-16 h-16 mb-4 flex items-center justify-center">
                   <LogoIcon className="w-full h-full text-slate-900 dark:text-white" />
                 </div>

                 <h2 className="text-xl font-black text-slate-900 dark:text-white mb-0.5">الدليل الطبي</h2>
                 <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 tracking-wider uppercase mb-6">صندوق الخدمات الطبية</p>

                 <div className="w-full space-y-3">
                    <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                          <ShieldCheck size={16} />
                          <span className="text-xs font-bold">الإصدار</span>
                       </div>
                       <span className="font-mono text-xs font-bold text-slate-900 dark:text-slate-200">1.2.0</span>
                    </div>

                    <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                          <Globe size={16} />
                          <span className="text-xs font-bold">التحديث</span>
                       </div>
                       <span className="text-xs font-bold text-slate-900 dark:text-slate-200">فبراير 2025</span>
                    </div>
                 </div>

                 <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-6 leading-relaxed max-w-[180px]">
                    تم تطوير هذا التطبيق لخدمة أعضاء الصندوق وتيسير الوصول للجهات العلاجية
                 </p>
              </div>
           </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

export default HomeScreen;

