import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { Search, MapPin, FileDown, ArrowUpCircle, ChevronRight, X, LayoutGrid, ShieldCheck, Globe, Moon, Sun, Building2, Microscope } from 'lucide-react';
import { HOSPITALS, LABS } from '../constants';
import HospitalCard from './HospitalCard';
import Toast from './Toast';
import BottomNav, { TabId } from './BottomNav';
import LogoIcon from './LogoIcon';

type ToastState = { message: string; type: 'success' | 'error' | 'info'; } | null;
type EntityType = 'hospitals' | 'labs';

interface HomeScreenProps {
  onBack: () => void;
  isDark: boolean;
  toggleTheme: () => void;
}

const HomeScreen: React.FC<HomeScreenProps> = ({ onBack, isDark, toggleTheme }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGov, setSelectedGov] = useState('');
  const [toast, setToast] = useState<ToastState>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeTab, setActiveTab] = useState<EntityType>('hospitals');
  const [navTab, setNavTab] = useState<TabId>('home');
  const [showAboutModal, setShowAboutModal] = useState(false);

  const mainRef = useRef<HTMLElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const currentData = useMemo(() => activeTab === 'hospitals' ? HOSPITALS : LABS, [activeTab]);

  const governorates = useMemo(() => {
    return Array.from(new Set(currentData.map((h) => h.gov))).sort();
  }, [currentData]);

  const filteredData = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    const phoneTerm = term.replace(/[\s-]/g, '');

    return currentData.filter((h) => {
      const matchGov = !selectedGov || h.gov === selectedGov;
      if (!term) return matchGov;

      const normalizedPhone = h.phone.replace(/[\s-]/g, '');

      return matchGov && (
        h.name.toLowerCase().includes(term) ||
        h.area.toLowerCase().includes(term) ||
        (phoneTerm.length > 2 && normalizedPhone.includes(phoneTerm))
      );
    });
  }, [searchTerm, selectedGov, currentData]);

  const handleScroll = useCallback(() => {
    const scrollY = mainRef.current?.scrollTop || 0;
    if (scrollY > 150 !== showScrollTop) setShowScrollTop(scrollY > 150);
    if (scrollY > 20 !== isScrolled) setIsScrolled(scrollY > 20);
  }, [showScrollTop, isScrolled]);

  useEffect(() => {
    const mainEl = mainRef.current;
    mainEl?.addEventListener('scroll', handleScroll, { passive: true });
    return () => mainEl?.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  useEffect(() => {
    setSearchTerm('');
    setSelectedGov('');
    mainRef.current?.scrollTo({ top: 0 });
  }, [activeTab]);

  const handleScrollToTop = () => mainRef.current?.scrollTo({ top: 0, behavior: 'smooth' });

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    setToast({ message, type });
  };

  const handleCall = useCallback((phone: string) => {
    if (!phone || phone === "-") {
      showToast("عفواً، الرقم غير متوفر", 'error');
      return;
    }
    window.location.href = `tel:${phone}`;
  }, []);

  const handleCopy = useCallback(async (phone: string) => {
    if (!navigator.clipboard) {
      showToast('المتصفح لا يدعم النسخ التلقائي', 'error');
      return;
    }
    try {
      await navigator.clipboard.writeText(phone);
      showToast('تم نسخ الرقم بنجاح');
    } catch {
      showToast('حدث خطأ أثناء النسخ', 'error');
    }
  }, []);

  const handlePrintPdf = () => {
    if (filteredData.length === 0) {
      showToast("لا توجد بيانات للطباعة", "error");
      return;
    }
    window.print();
  };

  const handleNavChange = (tab: TabId) => {
    if (tab === 'exit') {
      onBack();
      return;
    }

    setNavTab(tab);

    if (tab === 'home') {
      handleScrollToTop();
      setSearchTerm('');
      setSelectedGov('');
      setShowAboutModal(false);
    } else if (tab === 'search') {
      handleScrollToTop();
      setShowAboutModal(false);
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 300);
    } else if (tab === 'about') {
      setShowAboutModal(true);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fafbfc] dark:bg-[#020617] relative overflow-hidden font-cairo print:h-auto print:overflow-visible print:block transition-colors duration-300">

      {/* Print Header */}
      <div className="print-only p-8 border-b-2 border-black mb-6">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-black text-black mb-2">دليل {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل والأشعة'}</h1>
            <p className="text-sm font-bold text-gray-600">صندوق الخدمات الطبية - القوات المسلحة</p>
          </div>
          <div className="text-left">
            <p className="text-xs text-gray-500">تاريخ الاستخراج</p>
            <p className="font-mono font-bold text-lg">{new Date().toLocaleDateString('ar-EG')}</p>
          </div>
        </div>
      </div>

      {/* Minimalist Compact Header */}
      <header className={`bg-[#fafbfc]/95 dark:bg-[#020617]/95 backdrop-blur-md pt-safe transition-all duration-300 z-30 no-print sticky top-0 ${isScrolled ? 'border-b border-slate-200 dark:border-slate-800 shadow-sm' : ''}`}>
        <div className="flex flex-col px-4 pt-4 pb-2">

          {/* Top Row */}
          <div className="flex justify-between items-center mb-4">
            <button 
              onClick={onBack} 
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:bg-slate-200 transition-all active:scale-90"
            >
              <ChevronRight size={20} strokeWidth={2.5} />
            </button>

            <div className={`flex flex-col items-center transition-all duration-300 ${isScrolled ? 'opacity-0 scale-90 h-0' : 'opacity-100 scale-100'}`}>
               <LogoIcon className="w-10 h-10 mb-1 text-slate-900 dark:text-white" />
               <h1 className="text-lg font-black text-slate-900 dark:text-white tracking-tight">الدليل الطبي</h1>
            </div>

            {/* Scrolled Title */}
             <div className={`absolute left-1/2 -translate-x-1/2 font-black text-base text-slate-900 dark:text-white transition-all duration-300 ${isScrolled ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}`}>
                {activeTab === 'hospitals' ? 'المستشفيات' : 'المعامل'}
             </div>

             <div className="flex items-center gap-2">
               <button 
                onClick={toggleTheme} 
                className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-yellow-500 hover:bg-slate-200 transition-all active:scale-90"
              >
                {isDark ? <Sun size={20} /> : <Moon size={20} />}
              </button>

              <button 
                onClick={handlePrintPdf} 
                className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:bg-slate-200 transition-all active:scale-90"
              >
                <FileDown size={20} />
              </button>
             </div>
          </div>

          {/* Search Bar */}
          <div className="relative z-20 group">
             <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none">
                <Search className="text-slate-400 group-focus-within:text-slate-900 dark:group-focus-within:text-white transition-colors" size={20} />
             </div>
             <input
                ref={searchInputRef}
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={activeTab === 'hospitals' ? "ابحث باسم المستشفى..." : "ابحث باسم المعمل..."}
                className="w-full py-3 pr-11 pl-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-sm text-slate-900 dark:text-white placeholder:text-slate-400 font-bold focus:outline-none focus:border-slate-400 dark:focus:border-slate-600 transition-all shadow-sm"
             />
             {searchTerm && (
                <button 
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 left-3 flex items-center text-slate-400 hover:text-red-500"
                >
                  <X size={18} />
                </button>
             )}
          </div>

          {/* Filters Row */}
          <div className="flex gap-2 mt-3 overflow-x-auto pb-1 no-scrollbar">
             <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-lg shrink-0 border border-slate-200 dark:border-slate-800">
                <button 
                  onClick={() => setActiveTab('hospitals')}
                  className={`flex items-center gap-2 px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'hospitals' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  <Building2 size={16} />
                  <span>مستشفيات</span>
                </button>
                <button 
                  onClick={() => setActiveTab('labs')}
                  className={`flex items-center gap-2 px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'labs' ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  <Microscope size={16} />
                  <span>معامل</span>
                </button>
             </div>

             <div className="relative shrink-0 min-w-[140px]">
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                   <MapPin size={14} />
                </div>
                <select 
                  value={selectedGov}
                  onChange={(e) => setSelectedGov(e.target.value)}
                  className="w-full h-full pl-6 pr-9 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg text-xs font-bold text-slate-700 dark:text-slate-200 focus:outline-none appearance-none"
                >
                  <option value="">كل المحافظات</option>
                  {governorates.map(gov => <option key={gov} value={gov}>{gov}</option>)}
                </select>
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                  <ChevronRight size={14} className="-rotate-90" />
                </div>
             </div>
          </div>
        </div>
      </header>

      {/* Content */}
      <main 
        ref={mainRef} 
        className="flex-1 overflow-y-auto px-4 pb-32 pt-4 scroll-smooth z-10"
      >
        <div className="max-w-3xl mx-auto">
          <div className="grid grid-cols-1 gap-4 print-grid">
            {filteredData.length > 0 ? (
              filteredData.map((item, index) => (
                <HospitalCard 
                  key={`${item.name}-${index}`} 
                  hospital={item} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                  type={activeTab === 'labs' ? 'lab' : 'hospital'}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-slate-300 dark:text-slate-800">
                <Search size={64} strokeWidth={1} className="mb-4 opacity-20" />
                <p className="text-lg font-bold">لا توجد نتائج</p>
              </div>
            )}
          </div>

          <div className="mt-12 mb-6 flex flex-col items-center justify-center opacity-30 text-slate-400 dark:text-slate-600 no-print">
            <LogoIcon className="w-6 h-6 mb-2" />
            <p className="text-[10px] font-medium">تصميم وتطوير: أحمد عماد</p>
          </div>
        </div>
      </main>

      <BottomNav activeTab={navTab} onTabChange={handleNavChange} />

      <button
        onClick={handleScrollToTop}
        className={`no-print fixed bottom-24 right-4 z-30 p-3 bg-slate-900 dark:bg-slate-800 text-white rounded-full shadow-xl transition-all duration-500 transform ${
            showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-75 pointer-events-none'
        } hover:bg-black active:scale-90`}
      >
        <ArrowUpCircle size={24} strokeWidth={2.5} />
      </button>

      {/* Minimalist About Modal */}
      {showAboutModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/40 backdrop-blur-sm animate-fade-in-up" onClick={() => setShowAboutModal(false)}>
           <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-3xl p-8 shadow-2xl relative border border-slate-100 dark:border-slate-800" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowAboutModal(false)} className="absolute top-6 right-6 p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400 hover:text-black transition-colors">
                <X size={20} />
              </button>

              <div className="flex flex-col items-center text-center">
                 <div className="w-20 h-20 mb-6 flex items-center justify-center text-slate-900 dark:text-white">
                   <LogoIcon className="w-full h-full" />
                 </div>

                 <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">الدليل الطبي</h2>
                 <p className="text-xs font-bold text-slate-500 dark:text-slate-400 tracking-widest uppercase mb-8">صندوق الخدمات الطبية</p>

                 <div className="w-full space-y-4">
                    <div className="flex justify-between items-center py-3 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-3 text-slate-600 dark:text-slate-400">
                          <ShieldCheck size={20} />
                          <span className="text-sm font-bold">الإصدار</span>
                       </div>
                       <span className="font-mono text-sm font-bold text-slate-900 dark:text-white">1.2.0</span>
                    </div>

                    <div className="flex justify-between items-center py-3 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-3 text-slate-600 dark:text-slate-400">
                          <Globe size={20} />
                          <span className="text-sm font-bold">التحديث</span>
                       </div>
                       <span className="text-sm font-bold text-slate-900 dark:text-white">فبراير 2025</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

export default HomeScreen;

