import React from 'react';

export const LogoIcon: React.FC<{ className?: string }> = ({ className }) => {
  return (
    <svg 
      viewBox="0 0 100 86" 
      xmlns="http://www.w3.org/2000/svg" 
      className={className}
      fill="currentColor"
    >
      {/* 
        رسم دقيق بأسلوب الـ Grid للخط الكوفي المربع الظاهر في الصورة
        تم تقسيم التصميم إلى 3 صفوف رئيسية مع مراعاة الفراغات الدقيقة
      */}
      <g>
        {/* الصف الأول: صندوق */}
        <path d="M0 0h100v22H0V0zm3 3v16h94V3H3z"/>
