          </div>
        </div>
      </header>

      {/* Content */}
      <main 
        ref={mainRef} 
        className="flex-1 overflow-y-auto px-4 pb-28 pt-2 scroll-smooth z-10"
      >
        <div className="max-w-3xl mx-auto">
          <div className="grid grid-cols-1 gap-3 print-grid">
            {filteredData.length > 0 ? (
              filteredData.map((item, index) => (
                <HospitalCard 
                  key={`${item.name}-${index}`} 
                  hospital={item} 
                  onCall={handleCall} 
                  onCopy={handleCopy}
                  index={index}
                  type={activeTab === 'labs' ? 'lab' : 'hospital'}
                />
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-slate-300 dark:text-slate-700">
                <Search size={50} strokeWidth={1} className="mb-4 opacity-20" />
                <p className="text-base font-bold text-slate-400 dark:text-slate-600">لا توجد نتائج</p>
              </div>
            )}
          </div>

          <div className="mt-8 mb-4 flex flex-col items-center justify-center text-slate-300 dark:text-slate-700 no-print opacity-60">
