        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/40 backdrop-blur-sm animate-fade-in-up" onClick={() => setShowAboutModal(false)}>
           <div className="bg-white dark:bg-slate-900 w-full max-w-xs rounded-3xl p-6 shadow-2xl relative border border-slate-100 dark:border-slate-800" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowAboutModal(false)} className="absolute top-4 right-4 p-1.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400 hover:text-black transition-colors">
                <X size={16} />
              </button>

              <div className="flex flex-col items-center text-center">
                 <div className="w-16 h-16 mb-4">
                   <LogoIcon className="w-full h-full" />
                 </div>

                 <h2 className="text-xl font-black text-slate-900 dark:text-white mb-0.5">الدليل الطبي</h2>
                 <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 tracking-wider uppercase mb-6">صندوق الخدمات الطبية</p>

                 <div className="w-full space-y-3">
                    <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                          <ShieldCheck size={16} />
                          <span className="text-xs font-bold">الإصدار</span>
                       </div>
                       <span className="font-mono text-xs font-bold text-slate-900 dark:text-white">1.2.0</span>
                    </div>

                    <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-slate-800">
                       <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                          <Globe size={16} />
                          <span className="text-xs font-bold">التحديث</span>
                       </div>
                       <span className="text-xs font-bold text-slate-900 dark:text-white">فبراير 2025</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
};

