          <div className="flex gap-2 mt-2 overflow-x-auto pb-1 no-scrollbar">
             <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-lg shrink-0 border border-slate-200 dark:border-slate-800">
                <button 
